contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v) public payable {
        require(address(this).balance >= v, "insufficient test balance");

        // Fund c so that c's balance is a known setup value independent of v.
        (bool funded, ) = address(c).call{value: v}("");
        require(funded, "funding failed");

        uint256 balBefore = address(c).balance;

        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // Owner's withdraw: succeeds iff v <= c's balance, and on success c's balance is reduced by exactly v.
        assert(reverted == (v > balBefore) && (reverted || balAfter == balBefore - v));
    }

    receive() external payable {}
}

