contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value);

        // make target nonzero so its call has an effect
        uint beforeC = address(c).balance;

        bool reverted;
        try c.sendMoney{value: value}(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;

        // General rule: sendMoney either reverts, or it succeeds and moves
        // exactly `value` Ether out of c as part of the call.
        // (c starts with the Ether sent to it via its fallback; after a
        // successful sendMoney, c's balance must have decreased by `value`.)
        assert(!reverted || beforeC == afterC + value);
    }

    receive() external payable {}
}

