contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Fund c with the given amount; also increments depositsCount.
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address beforeOwner = c.owner();

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the caller is the owner only if the contract itself is the owner.
        // In this deployment msg.sender for every c call is this InvMutTest contract.
        // So withdrawAll must succeed (not revert), move c's entire balance to this caller,
        // and leave c with zero balance; depositsCount is unaffected.
        assert(
            !reverted &&
            beforeOwner == address(this) &&
            address(c).balance == 0 &&
            address(this).balance >= beforeBalance &&
            c.depositsCount() == beforeDeposits
        );
    }

    receive() external payable {}
}

