contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint withdrawAmount) public payable {
        require(address(this).balance >= withdrawAmount);

        // Record pre-state observable through c's public surface
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Fund c (onlyOwner sendMoney to c itself — owner is this test contract)
        c.sendMoney{value: withdrawAmount}(address(c), withdrawAmount, "");

        uint fundedBalance = address(c).balance;

        // Read owner via public getter
        address ownerAddr = c.owner();
        bool isOwner = (ownerAddr == address(this));

        // Attempt withdrawAll as owner (msg.sender is this test contract)
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // General rule: as owner, withdrawAll never reverts, moves entire balance
        // to the caller, and depositsCount is unchanged.
        assert(
            isOwner && !reverted &&
            afterBalance == 0 &&
            c.depositsCount() == beforeDeposits
        );
    }

    receive() external payable {}
}

