contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint value) public payable {
        // Ensure this contract has enough Ether to fund c and to exercise withdraw
        require(address(this).balance >= value);

        // Drive c through its public payable fallback so c holds Ether; setup is a top-level call
        uint beforeCaller0 = address(this).balance;
        uint beforeC0 = address(c).balance;
        (bool sentOk, ) = address(c).call{value: value}("");
        require(sentOk);

        // The initial added balance did not affect the caller's net outcome beyond value
        // (it is exactly the value we sent, recorded here for the assert)
        uint addedToC = address(c).balance - beforeC0;

        // Now decide the rule with the public entry withdraw
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCaller = address(this).balance;
        uint afterC = address(c).balance;

        // General rule: the call succeeds iff the caller (the owner) is passed a value no larger
        // than c's balance at call time, which is beforeC0 + addedToC. On success the caller
        // receives exactly value and c loses exactly value; otherwise it reverts and no balances move.
        assert(
            (
                (beforeC0 + addedToC >= value)
                    ? (!reverted && afterCaller == beforeCaller0 + addedToC - value && afterC == beforeC0 + addedToC - value)
                    : (reverted && afterCaller == beforeCaller0 + addedToC && afterC == beforeC0 + addedToC)
            )
        );
    }

    receive() external payable {}
}

